def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """

    def fib():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    fib_numbers = fib()
    prime_count = 0
    for number in fib_numbers:
        if is_prime(number):
            prime_count += 1
            if prime_count == n:
                return number

