from typing import List
def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    visited = set()
    min_path = []
    min_length = float('inf')

    def dfs(x, y, path, length):
        nonlocal min_path, min_length
        if length == k:
            if length < min_length:
                min_length = length
                min_path = path[:]
            return
        if (x, y) in visited:
            return
        visited.add((x, y))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                dfs(nx, ny, path + [grid[nx][ny]], length + 1)
        visited.remove((x, y))

    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]], 1)

    return min_path

